<template>
  <section ref="root" class="story-editor" :class="[{ 'story-editor--fullscreen': fullscreen }, isDark ? 'story-editor--dark' : 'story-editor--light', `story-editor--${document.settings.density}`]">
    <Teleport to="#global-account-slot"><AccountPanel :archive="archive" @load="$emit('change',$event)" @sync="$emit('sync',$event)" /></Teleport>
    <Teleport to="#global-title-slot"><div class="story-title">
        <div><input v-if="titleEditing" ref="titleInput" v-model="titleDraft" class="story-title-input" maxlength="120" aria-label="故事名" @blur="saveTitle" @keydown.enter.prevent="saveTitle" @keydown.esc.prevent="cancelTitleEdit" /><strong v-else>{{ document.title }}</strong><button v-if="!titleEditing" class="title-edit" title="修改故事名" aria-label="修改故事名" @click="startTitleEdit">✎</button></div>
        <small>{{ document.messages.length }} 条消息 · {{ document.characters.length - 1 }} 个角色 · {{ readableCharacterCount }} 字</small>
      </div></Teleport>
    <Teleport to="#global-actions-slot"><div class="story-editor__header-actions">
        <button class="header-action header-action--icon" title="上传旧日志或 SSP" aria-label="上传旧日志或 SSP" @click="$emit('import')"><IconUpload aria-hidden="true" /></button>
        <div class="download-menu"><button class="header-action header-action--icon" title="下载与导出" aria-label="下载与导出" :aria-expanded="downloadMenuOpen" @click="downloadMenuOpen=!downloadMenuOpen"><IconDownload aria-hidden="true" /></button><Transition name="resource-pop"><nav v-if="downloadMenuOpen" aria-label="下载格式"><button class="download-item download-item--ssp" @click="downloadMenuOpen=false;$emit('download')">SSP 工程包<small>Ctrl+S</small></button><button class="download-item download-item--legacy" @click="downloadMenuOpen=false;$emit('legacy-text')">传统日志 TXT<small>经典版可导入</small></button><button class="download-item download-item--html" @click="downloadMenuOpen=false;$emit('html')">内嵌 HTML</button><button class="download-item download-item--word" @click="downloadMenuOpen=false;$emit('word')">传统 Word</button><button class="download-item download-item--image" @click="downloadMenuOpen=false;$emit('long-image')">预览长图</button></nav></Transition></div>
        <button class="header-action header-action--icon" :class="{ active: rawActive }" :title="rawActive?'返回图形编辑':'编辑原始语法'" :aria-label="rawActive?'返回图形编辑':'编辑原始语法'" @click="$emit('raw')"><IconCode aria-hidden="true" /></button>
        <button class="header-action header-action--icon" :class="{ active: fullscreen }" :title="fullscreen?'退出全屏编辑':'全屏编辑'" :aria-label="fullscreen?'退出全屏编辑':'全屏编辑'" @click="toggleFullscreen"><svg viewBox="0 0 24 24" aria-hidden="true"><path v-if="!fullscreen" d="M8 3H3v5M16 3h5v5M8 21H3v-5M16 21h5v-5"/><path v-else d="M3 8h5V3M21 8h-5V3M3 16h5v5M21 16h-5v5"/></svg></button>
        <div class="more-menu"><button class="header-action more-trigger" title="更多" aria-label="更多" :aria-expanded="moreMenuOpen" @click="moreMenuOpen=!moreMenuOpen"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="19" cy="12" r="1.4"/></svg><span>更多</span></button><Transition name="resource-pop"><nav v-if="moreMenuOpen"><button @click="moreMenuOpen=false;displaySettingsOpen=true"><span>界面与输入设置</span><small>画布、头像、回车行为</small></button><button class="danger" @click="moreMenuOpen=false;$emit('clear')"><span>删除本地修改</span><small>需要二次确认</small></button></nav></Transition></div>
		<button class="header-action primary preview-action" title="演出编辑预览" aria-label="演出编辑预览" @click="$emit('preview')"><IconPlay aria-hidden="true" /><span>演出编辑预览</span></button>
      </div></Teleport>
	<main ref="messageList" :style="canvasStyle" @click="actionMenuId=''" @scroll.passive="scheduleStickyAvatar">
	  <div v-if="stickyCharacter" class="sticky-avatar" :style="stickyAvatarStyle"><span class="avatar" :style="roleStyle(stickyCharacter)"><img v-if="avatar(stickyCharacter)" :src="avatar(stickyCharacter)" alt="" /><span v-else>{{ stickyCharacter.name.slice(0,1) }}</span></span></div>
      <div v-if="!document.messages.length" class="empty">还没有消息。请从下方选择角色并开始写作。</div>
	  <div v-else ref="virtualList" class="virtual-message-list" :style="{height:`${messageVirtualizer.getTotalSize()}px`}">
	  <div v-for="{message,index,row} in virtualEntries" :key="String(row.key)" :ref="measureVirtualRow" class="virtual-message-row" :class="{'virtual-message-row--menu-open':actionMenuId===message.id}" :data-index="index" :style="{transform:`translateY(${row.start}px)`}">
	  <div v-if="insertBatch&&insertTarget===message.id&&insertDirection==='above'" class="batch-insert-marker"><i></i><span>多插位置 · 下一条会插在这里</span><button @click="insertDirection='below'">移到下方</button><button class="danger" @click="cancelInsert">结束</button></div>
      <article v-if="desktopInsert && insertTarget===message.id && insertDirection==='above'" class="story-message story-message--inline-insert" :class="`story-message--${selectedCharacter()?.position || 'left'}`" @click.stop><span v-if="insertAvatarSlot()" class="avatar-slot"><button class="avatar"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button></span><div class="story-message__content"><small v-if="document.settings.showNames && selectedCharacter()?.position!=='narrator'"><span class="character-name">{{ selectedCharacter()?.name }}</span><span v-if="document.settings.showQqInEditor && selectedCharacter()?.imUserId" class="character-account"> · {{ selectedCharacter()?.imUserId }}</span></small><div class="bubble" :class="{ 'bubble--narrator-avatar': insertNarratorAvatar() }"><div v-if="insertNarratorAvatar()" class="narrator-identity"><button class="narrator-avatar" @click.stop="selectedCharacterId && selectCharacter(selectedCharacterId)"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button><span v-if="insertNarratorName()" class="narrator-identity__text"><span class="character-name">{{ selectedCharacter()?.name }}</span><span v-if="document.settings.showQqInEditor && selectedCharacter()?.imUserId" class="character-account"> · {{ selectedCharacter()?.imUserId }}</span></span></div><textarea ref="insertArea" v-model="insertDraft" :rows="insertBatch?4:1" :placeholder="insertBatch?'每行一条消息；Ctrl+Enter 插入':'插入一条消息；Enter 确认'" @keydown.enter.exact.prevent="insertBatch?undefined:addInsertedMessages()" @keydown.ctrl.enter.prevent="addInsertedMessages" @keydown.esc.prevent="cancelInsert" /></div></div><div class="inline-insert-actions"><button v-if="insertBatch" @click="insertDirection='below'">改为下插</button><button title="添加图片" @click="imageInput?.click()">图</button><button class="primary" :disabled="!insertDraft.trim()" @click="addInsertedMessages">✓</button><button @click="cancelInsert">✕</button></div></article>
      <article :data-id="message.id" class="story-message" :class="[`story-message--${character(message.characterId)?.position || 'left'}`, `story-message--group-${groupPosition(index)}`, { 'story-message--selected': selected.has(message.id), 'story-message--menu-open': actionMenuId===message.id, 'story-message--move-mode':moveMode } ]" :style="messageStyle(message)" @click="selectMessage(message.id)">
        <button v-if="moveMode" class="drag" title="拖动消息" aria-label="拖动消息" @pointerdown.stop="startDirectDrag($event,message.id)" @contextmenu.prevent @click.stop>⠿</button>
        <span v-if="avatarSlot(index)" class="avatar-slot" :class="{ 'avatar-slot--bottom': document.settings.avatarAlignment==='bottom' }"><button v-if="showAvatar(index)" class="avatar" @click.stop="selectCharacter(message.characterId)"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><span v-else>{{ character(message.characterId)?.name?.slice(0,1) || '旁' }}</span></button></span>
        <div class="story-message__content">
          <small v-if="showOutsideName(index) || document.settings.showTime"><template v-if="showOutsideName(index)"><span class="character-name">{{ character(message.characterId)?.name }}</span><span v-if="document.settings.showQqInEditor && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></template><span v-if="document.settings.showTime" class="message-time">{{ showOutsideName(index) ? ' · ' : '' }}{{ messageTime(message) }}</span></small>
		  <div class="bubble" :class="{ 'bubble--narrator-avatar': showNarratorBubbleAvatar(index) }" :style="editingId===message.id && !mobileEditing && editingBubbleWidth ? {width:`${editingBubbleWidth}px`,maxWidth:'100%',boxSizing:'border-box'} : undefined">
			<button v-if="message.replyToId" class="reply-preview" type="button" @click.stop="scrollToMessage(message.replyToId)"><strong :style="roleStyle(replyCharacter(message.replyToId))">{{ replyCharacter(message.replyToId)?.name || '原消息' }}</strong><span>{{ replySummary(message.replyToId) }}</span></button>
            <div v-if="showNarratorBubbleAvatar(index)" class="narrator-identity"><button class="narrator-avatar" @click.stop="selectCharacter(message.characterId)"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><span v-else>{{ character(message.characterId)?.name?.slice(0,1) || '旁' }}</span></button><span v-if="showNarratorName(index)" class="narrator-identity__text"><span class="character-name">{{ character(message.characterId)?.name }}</span><span v-if="document.settings.showQqInEditor && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></span></div>
			<img v-if="message.kind==='image'&&resourceAvailable(message.asset)" class="story-image" :src="asset(message.asset)" :alt="message.alt || '图片'" @error="markResourceInvalid(message.asset)" @click.stop="openImage(message)" />
			<div v-else-if="message.kind==='audio'" class="audio-content"><StoryAudioBubble v-if="resourceAvailable(message.asset)" :src="asset(message.asset)" :duration-ms="message.durationMs" :seed="message.id" @error="markResourceInvalid(message.asset)" /><span v-else class="resource-placeholder">【语音】</span><textarea v-if="editingId===message.id && !mobileEditing" ref="editArea" v-model="editText" rows="1" placeholder="添加人工转写或声音描述（可留空）" @input="resizeTextArea" @keydown.enter.exact.prevent="commitEdit(message.id)" @keydown.esc.prevent="cancelEdit" /><p v-else-if="message.caption" class="audio-caption">{{ message.caption }}</p></div>
			<span v-else-if="message.kind==='image'" class="resource-placeholder">【图片】</span>
			<textarea v-else-if="editingId===message.id && !mobileEditing" ref="editArea" v-model="editText" rows="1" @input="resizeTextArea" @keydown.enter.exact.prevent="commitEdit(message.id)" @keydown.esc.prevent="cancelEdit" />
			<span v-else><template v-for="(segment,segmentIndex) in textSegments(message.text)" :key="segmentIndex"><img v-if="segment.faceId" class="inline-cq-face" :src="`/api/editor/cq-face/${segment.faceId}`" :alt="`QQ 表情 ${segment.faceId}`" /><span v-else :class="{'inline-mention':segment.character}" :style="segment.character?roleStyle(segment.character):undefined">{{ segment.text }}</span></template></span>
          </div>
        </div>
        <div v-if="!document.settings.previewOnly" class="message-actions" :class="{ 'message-actions--open': actionMenuId===message.id }">
          <button class="message-edit" title="消息操作" aria-label="消息操作" @click.stop="toggleActionMenu(message.id,$event)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20l4.2-1 10.6-10.6a2.1 2.1 0 0 0-3-3L5.2 16 4 20Z"/><path d="m13.8 6.2 4 4"/></svg></button>
          <Transition name="message-pop"><div v-if="actionMenuId===message.id" class="message-menu" :style="{'--message-menu-offset':`${actionMenuOffset}px`}" role="menu" aria-label="消息操作"><button role="menuitem" class="danger" @click.stop="actionMenuId='';removeSelected(message.id)"><b>⌫</b>删除</button><button v-if="message.kind==='text'||message.kind==='audio'" role="menuitem" @click.stop="startEdit(message)"><b>✎</b>{{ message.kind==='audio'?'注释':'编辑' }}</button><button role="menuitem" @click.stop="startReply(message.id)"><b>↩</b>引用</button><button role="menuitem" @click.stop="beginSelection(message.id)"><b>✓</b>{{ selected.has(message.id)?'取消选择':'多选' }}</button><button v-if="moveMode" role="menuitem" @click.stop="moveSelectedMessages(message.id,-1)"><b>⇡</b>上移</button><button v-if="moveMode" role="menuitem" @click.stop="moveSelectedMessages(message.id,1)"><b>⇣</b>下移</button><button role="menuitem" @click.stop="openInsert(message.id,'above');actionMenuId=''"><b>↑</b>上插</button><button role="menuitem" @click.stop="openInsert(message.id,'below');actionMenuId=''"><b>↓</b>下插</button><button role="menuitem" @click.stop="openBatchInsert(message.id)"><b>≡</b>多插</button></div></Transition>
        </div>
      </article>
      <article v-if="desktopInsert && insertTarget===message.id && insertDirection==='below'" class="story-message story-message--inline-insert" :class="`story-message--${selectedCharacter()?.position || 'left'}`" @click.stop><span v-if="insertAvatarSlot()" class="avatar-slot"><button class="avatar"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button></span><div class="story-message__content"><small v-if="document.settings.showNames && selectedCharacter()?.position!=='narrator'"><span class="character-name">{{ selectedCharacter()?.name }}</span><span v-if="document.settings.showQqInEditor && selectedCharacter()?.imUserId" class="character-account"> · {{ selectedCharacter()?.imUserId }}</span></small><div class="bubble" :class="{ 'bubble--narrator-avatar': insertNarratorAvatar() }"><div v-if="insertNarratorAvatar()" class="narrator-identity"><button class="narrator-avatar" @click.stop="selectedCharacterId && selectCharacter(selectedCharacterId)"><img v-if="avatar(selectedCharacter())" :src="avatar(selectedCharacter())" alt="" /><span v-else>{{ selectedCharacter()?.name?.slice(0,1) || '旁' }}</span></button><span v-if="insertNarratorName()" class="narrator-identity__text"><span class="character-name">{{ selectedCharacter()?.name }}</span><span v-if="document.settings.showQqInEditor && selectedCharacter()?.imUserId" class="character-account"> · {{ selectedCharacter()?.imUserId }}</span></span></div><textarea ref="insertArea" v-model="insertDraft" :rows="insertBatch?4:1" :placeholder="insertBatch?'每行一条消息；Ctrl+Enter 插入':'插入一条消息；Enter 确认'" @keydown.enter.exact.prevent="insertBatch?undefined:addInsertedMessages()" @keydown.ctrl.enter.prevent="addInsertedMessages" @keydown.esc.prevent="cancelInsert" /></div></div><div class="inline-insert-actions"><button v-if="insertBatch" @click="insertDirection='above'">改为上插</button><button title="添加图片" @click="imageInput?.click()">图</button><button class="primary" :disabled="!insertDraft.trim()" @click="addInsertedMessages">✓</button><button @click="cancelInsert">✕</button></div></article>
	  <div v-if="insertBatch&&insertTarget===message.id&&insertDirection==='below'" class="batch-insert-marker"><i></i><span>多插位置 · 下一条会插在这里</span><button @click="insertDirection='above'">移到上方</button><button class="danger" @click="cancelInsert">结束</button></div>
	  </div>
	  </div>
    </main>

    <section v-if="!document.settings.previewOnly" class="composer">
	  <div v-if="insertBatch" class="composer-reply composer-batch"><span><strong>多插中</strong>选择下方角色，发送后会依次插入标记位置</span><button class="composer-batch__end" title="退出多插" aria-label="退出多插" @click="cancelInsert">退出多插</button></div>
	  <div v-if="moveMode" class="composer-reply composer-batch"><span><strong>批量移动</strong>已选择 {{ selected.size }} 条消息</span><div><button :disabled="!selected.size" title="整体上移" @click="moveSelection(-1)">↑ 上移</button><button :disabled="!selected.size" title="整体下移" @click="moveSelection(1)">↓ 下移</button><button @click="moveMode=false">完成</button></div></div>
	  <div v-if="composerReplyId" class="composer-reply"><span><strong>{{ replyCharacter(composerReplyId)?.name || '原消息' }}</strong>{{ replySummary(composerReplyId) }}</span><button title="取消引用" aria-label="取消引用" @click="composerReplyId=''">✕</button></div>
	  <div class="emoji-picker"><button class="icon-square" title="表情" aria-label="表情" :aria-expanded="emojiPickerOpen" @click="toggleEmojiPicker"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M8.5 14.5c1 1.4 2.1 2 3.5 2s2.5-.6 3.5-2M9 9.5h.01M15 9.5h.01"/></svg></button><Transition name="resource-pop"><section v-if="emojiPickerOpen" class="emoji-panel emoji-panel--desktop"><header><strong>选择表情</strong><button aria-label="关闭表情" @click="emojiPickerOpen=false">✕</button></header><nav><button :class="{active:emojiTab==='emoji'}" @click="emojiTab='emoji'">Emoji</button><button :class="{active:emojiTab==='qq'}" @click="emojiTab='qq'">QQ 表情</button></nav><div v-if="emojiTab==='emoji'" class="emoji-grid"><button v-for="emoji in commonEmoji" :key="emoji" @click="insertEmoji(emoji)">{{ emoji }}</button></div><div v-else class="emoji-grid emoji-grid--qq"><button v-for="id in qqFaceIds" :key="id" :title="`QQ 表情 ${id}`" @click="insertQqFace(id)"><img loading="lazy" :src="`/api/editor/cq-face/${id}`" :alt="`QQ 表情 ${id}`" @error="hideBrokenFace" /></button></div></section></Transition></div>
      <StoryComposerInput ref="composerInput" v-model="draft" placeholder="请输入文本" @input="resizeComposer" @keydown="handleComposerKeydown" @keyup="handleComposerKeyup" />
      <div class="composer-actions"><template v-if="!draft.trim()"><div class="resource-add"><button class="icon-square resource-add__trigger" title="添加资源" aria-label="添加资源" :aria-expanded="resourceMenuOpen" @click="resourceMenuOpen=!resourceMenuOpen"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg></button><Transition name="resource-pop"><nav v-if="resourceMenuOpen" aria-label="添加资源"><header><strong>添加资源</strong><button aria-label="关闭资源菜单" @click="resourceMenuOpen=false">✕</button></header><div><button @click="resourceMenuOpen=false;imageInput?.click()"><svg class="resource-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m5 17 4.5-4.5 3.2 3.2 2.2-2.2L19 17"/></svg><span>图片</span><small>从设备选择并压缩</small></button><button @click="resourceMenuOpen=false;audioInput?.click()"><svg class="resource-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 13v-2M8 16V8M12 19V5M16 16V8M20 13v-2"/></svg><span>语音</span><small>压缩为 128kbps Opus</small></button><button @click="resourceMenuOpen=false;openMediaUrl()"><svg class="resource-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m10 14 4-4"/><path d="M7.5 16.5 5.7 18.3a3.5 3.5 0 0 1-5-5l3.6-3.6a3.5 3.5 0 0 1 5 0" transform="translate(3)"/><path d="m16.5 7.5 1.8-1.8a3.5 3.5 0 0 1 5 5l-3.6 3.6a3.5 3.5 0 0 1-5 0" transform="translate(-3)"/></svg><span>链接</span><small>验证直链，不存服务端</small></button></div></nav></Transition></div><button class="icon-square settings-trigger" title="设置" aria-label="设置" @click="displaySettingsOpen=true"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-1.42 1.42-.06-.06a1.7 1.7 0 0 0-1.88-.34 1.7 1.7 0 0 0-1 1.55V20h-2v-.09A1.7 1.7 0 0 0 12.36 18a1.7 1.7 0 0 0-1.88.34l-.06.06L9 16.94l.06-.06A1.7 1.7 0 0 0 9.4 15a1.7 1.7 0 0 0-1.55-1H7v-2h.85A1.7 1.7 0 0 0 9.4 11a1.7 1.7 0 0 0-.34-1.88L9 9.06l1.42-1.42.06.06a1.7 1.7 0 0 0 1.88.34A1.7 1.7 0 0 0 13.4 6.5V6h2v.5A1.7 1.7 0 0 0 16.44 8a1.7 1.7 0 0 0 1.88-.34l.06-.06L19.8 9l-.06.06A1.7 1.7 0 0 0 19.4 11a1.7 1.7 0 0 0 1.55 1H21v2h-.05A1.7 1.7 0 0 0 19.4 15Z"/></svg></button></template><template v-else><button class="primary icon-square send-button" title="发送" aria-label="发送" @click="addMessages">发送</button></template></div>
      <input ref="imageInput" hidden type="file" accept="image/*" @change="addImage" />
      <input ref="audioInput" hidden type="file" accept="audio/*" @change="addAudio" />
    </section>

    <section v-if="!document.settings.previewOnly" class="character-dock" :class="{'character-dock--expanded':charactersExpanded}">
      <button class="character-dock__fixed character-dock__manage" @click="characterOverviewOpen=true"><span>♙</span><small>角色总览</small></button>
      <nav ref="characterRail" class="characters" aria-label="角色选择" @wheel="scrollCharacters">
        <button v-for="item in document.characters" :key="item.id" :class="{active:selectedCharacterId===item.id}" :style="roleStyle(item)" @click="characterClick(item)">
          <span class="character-avatar"><img v-if="avatar(item)" :src="avatar(item)" alt="" /><i v-else>{{ item.name.slice(0,1) }}</i></span><small>{{ item.name }}</small>
        </button>
        <button class="character-add" @click="newCharacter"><span class="character-avatar character-avatar--add">＋</span><small>新增角色</small></button>
      </nav>
      <button class="character-dock__fixed character-dock__toggle" :aria-expanded="charactersExpanded" @click="charactersExpanded=!charactersExpanded"><span><svg viewBox="0 0 24 24" aria-hidden="true" :class="{'is-expanded':charactersExpanded}"><path d="m6.5 9.5 5.5 5 5.5-5" /></svg></span><small>{{ charactersExpanded?'收起':'展开' }}</small></button>
    </section>
    <Transition name="emoji-keyboard"><section v-if="emojiPickerOpen" class="emoji-keyboard" aria-label="表情键盘"><header><strong>选择表情</strong><button aria-label="收起表情键盘" @click="emojiPickerOpen=false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6.5 9.5 5.5 5 5.5-5"/></svg></button></header><nav><button :class="{active:emojiTab==='emoji'}" @click="emojiTab='emoji'">Emoji</button><button :class="{active:emojiTab==='qq'}" @click="emojiTab='qq'">QQ 表情</button></nav><div v-if="emojiTab==='emoji'" class="emoji-grid"><button v-for="emoji in commonEmoji" :key="emoji" @click="insertEmoji(emoji)">{{ emoji }}</button></div><div v-else class="emoji-grid emoji-grid--qq"><button v-for="id in qqFaceIds" :key="id" :title="`QQ 表情 ${id}`" @click="insertQqFace(id)"><img loading="lazy" :src="`/api/editor/cq-face/${id}`" :alt="`QQ 表情 ${id}`" @error="hideBrokenFace" /></button></div></section></Transition>

    <Teleport to="body"><Transition name="modal-fade"><div v-if="displaySettingsOpen" class="settings-modal" @click.self="displaySettingsOpen=false"><section>
