function previewDisplaySetting(key:DisplaySettingKey,value:number){displayPreview[key]=value;stickyCharacterId.value='';const target=messageList.value;if(!target)return;target.style.setProperty('--canvas-width',`${displayPreview.canvasWidth}px`);target.style.setProperty('--avatar-size',`${displayPreview.avatarSize}px`);target.style.setProperty('--narrator-avatar-size',`${displayPreview.narratorAvatarSize}px`);target.style.setProperty('--font-size',`${displayPreview.fontSize}px`);target.style.setProperty('--bubble-width',`${Math.round(720*displayPreview.bubbleMaxWidth/100)}px`);target.style.setProperty('--side-gutter',`${displayPreview.centerGutterPercent/2}%`);target.style.setProperty('--image-max-width',`${Math.round(displayPreview.canvasWidth*displayPreview.imageMaxWidthPercent/100)}px`)}
