function updateVirtualStickyAvatar(){const list=messageList.value;if(!list||!document.value.settings.stickyGroupAvatar||!document.value.settings.showAvatars){stickyCharacterId.value='';return}const listRect=list.getBoundingClientRect();const topMode=document.value.settings.avatarAlignment==='top';const edge=topMode?listRect.top+12:listRect.bottom-12;const articles=Array.from(list.querySelectorAll<HTMLElement>('.virtual-message-row .story-message[data-id]'));const candidates=(topMode?articles:[...articles].reverse());const article=candidates.find(node=>{const rect=node.getBoundingClientRect();return topMode?rect.bottom>edge:rect.top<edge});if(!article){stickyCharacterId.value='';return}const row=article.closest<HTMLElement>('.virtual-message-row');const index=Number(row?.dataset.index);const message=displayMessages.value[index];const item=message?character(message.characterId):undefined;const rect=article.getBoundingClientRect();const position=Number.isFinite(index)?groupPosition(index):'single';const groupContinues=topMode?['middle','last'].includes(position):['first','middle'].includes(position);const crossed=topMode?rect.top<edge:rect.bottom>edge;if(!item||item.isNarrator||item.position==='narrator'||(!crossed&&!groupContinues)){stickyCharacterId.value='';return}stickyCharacterId.value=item.id;const style:Record<string,string>={};if(topMode)style.top=`${edge}px`;else style.bottom=`${Math.max(12,innerHeight-edge)}px`;if(item.position==='right')style.right=`${Math.max(8,innerWidth-rect.right)}px`;else style.left=`${Math.max(8,rect.left)}px`;stickyAvatarStyle.value=style}
