function captureVisibleMessageTops(){const result=new Map<string,number>();messageList.value?.querySelectorAll<HTMLElement>('.story-message[data-id]').forEach(node=>{if(node.dataset.id)result.set(node.dataset.id,node.getBoundingClientRect().top)});return result}function animateVisibleMessageMoves(previous:Map<string,number>){if(globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches)return;messageList.value?.querySelectorAll<HTMLElement>('.story-message[data-id]').forEach(node=>{const before=node.dataset.id?previous.get(node.dataset.id):undefined;if(before===undefined)return;const delta=before-node.getBoundingClientRect().top;if(Math.abs(delta)<1)return;node.animate([{transform:`translateY(${delta}px)`},{transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.75,.25,1)'})})}function toggleActionMenu(id:string,event:MouseEvent){if(actionMenuId.value===id){actionMenuId.value='';return}const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();const menuWidth=Math.min(336,globalThis.innerWidth-16);const menuLeft=Math.max(8,Math.min(rect.left,globalThis.innerWidth-menuWidth-8));actionMenuOffset.value=menuLeft-rect.left;actionMenuId.value=id}function toggleMessageSelection(id:string){if(selected.has(id)){selected.delete(id);if(!selected.size)moveMode.value=false}else selected.add(id)}function selectMessage(id:string){if(!moveMode.value)return;toggleMessageSelection(id)}function beginSelection(id:string){moveMode.value=true;toggleMessageSelection(id);actionMenuId.value=''}function moveSelection(direction:-1|1){if(!selected.size)return;const previous=captureVisibleMessageTops();const chosen=new Set(selected);const anchor=[...chosen][0];update(a=>{const messages=[...a.document.messages];if(direction<0){for(let index=1;index<messages.length;index+=1){if(chosen.has(messages[index].id)&&!chosen.has(messages[index-1].id))[messages[index-1],messages[index]]=[messages[index],messages[index-1]]}}else{for(let index=messages.length-2;index>=0;index-