function startEdit(message:StoryMessage){if(message.kind!=='text'&&message.kind!=='audio')return;const selector=`[data-id="${globalThis.CSS.escape(message.id)}"] .bubble`;editingBubbleWidth.value=Math.ceil(root.value?.querySelector<HTMLElement>(selector)?.getBoundingClientRect().width||0);actionMenuId.value='';editingId.value=message.id;editText.value=message.kind==='audio'?message.caption||'':message.text;editCharacterId.value=message.characterId;mobileEditing.value=globalThis.matchMedia('(max-width:650px)').matches;nextTick(()=>{const area=root.value?.querySelector<HTMLTextAreaElement>(`[data-id="${globalThis.CSS.escape(message.id)}"] textarea`);if(area){area.style.height='auto';area.style.height=`${Math.min(420,area.scrollHeight)}px`;area.focus()}else editArea.value?.[0]?.focus()})}function resizeTextArea(event:Event){const area=event.target as HTMLTextAreaElement;area.style.height='auto';area.style.height=`${Math.min(420,area.scrollHeight)}px`}function cancelEdit(){editingId.value='';editText.value='';editCharacterId.value='';editingBubbleWidth.value=0;mobileEditing.value=false}function commitEdit(id:string){const value=editText.value.trim();const current=document.value.messages.find(item=>item.id===id);if(!current||current.kind==='text'&&!value)return;update(a=>{const m=a.document.messages.find(v=>v.id===id);if(m?.kind==='text')m.text=value;else if(m?.kind==='audio')m.caption=value||undefined;if(m&&editCharacterId.value)m.characterId=editCharacterId.value});cancelEdit()}
function openInsert(id:string,direction:'above'|'below'){insertTarget.value=id;insertDirection.value=direction;insertBatch.value=false;insertDraft.value='';mobileInsert.value=globalThis.matchMedia('(max-width:650px)').matches;desktopInsert.value=!mobileInsert.value;nextTick(()=>insertArea.value?.[0]?.focus())}function openBatchInsert(id:string){actionMenuId.value='';insertTarget.value=id;insertDirection.value='below';insertBatch.value=true;insertDraft.value='';mobileInsert.value=false;desktopInsert.value=false;nextTick(()=>composerInput.value?.focus())}function cancelInsert(){insertTarget.value='';insertDraft.value='';insertBatch.value=false;desktopInsert.value=false;mobileInsert.value=false}
