function isCompactInput(){return globalThis.matchMedia('(max-width:650px),(pointer:coarse)').matches}function isIOSInput(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}function insertComposerNewline(){composerInput.value?.insertNewline()}function handleComposerKeydown(event:KeyboardEvent){if(event.key!=='Enter'||event.isComposing)return;if(event.ctrlKey||event.metaKey){event.preventDefault();addMessages();return}const behavior=document.value.settings.enterKeyBehavior||'auto';if(behavior==='newline')return;if(behavior==='send'){if(!event.shiftKey){event.preventDefault();addMessages()}return}if(!isCompactInput()){if(!event.shiftKey){event.preventDefault();addMessages()}return}if(isIOSInput()&&!event.shiftKey){event.preventDefault();if(event.repeat){if(!iosEnterHeld){window.clearTimeout(iosEnterTimer);iosEnterHeld=true;insertComposerNewline()}return}iosEnterHeld=false;window.clearTimeout(iosEnterTimer);iosEnterTimer=window.setTimeout(()=>{iosEnterHeld=true;insertComposerNewline()},420)}}function handleComposerKeyup(event:KeyboardEvent){if((document.value.settings.enterKeyBehavior||'auto')!=='auto'||event.key!=='Enter'||!isCompactInput()||!isIOSInput()||event.shiftKey)return;window.clearTimeout(iosEnterTimer);if(!iosEnterHeld)addMessages();iosEnterHeld=false}
