async function prepareUploadedMedia(file:File,kind:'image'|'audio',task?:UploadTask){const original=new Uint8Array(await file.arrayBuffer());if(task)task.status='正在上传并进行服务端压缩…';try{const response=await fetch('/api/editor/resources',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-Resource-Kind':kind},body:original});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).error||'服务端未能处理资源');const result=await response.json() as {id:string;url:string;reused:boolean};if(task)task.status=result.reused?'发现相同资源，正在复用…':'压缩完成，正在写入工程…';const optimizedResponse=await fetch(result.url);if(!optimizedResponse.ok)throw new Error('压缩后的资源无法读取');const bytes=new Uint8Array(await optimizedResponse.arrayBuffer());return{bytes,asset:{id:result.id,mime:optimizedResponse.headers.get('content-type')||file.type||`${kind}/*`,name:file.name} as StoryAssetRef}}catch(error){if(task)task.status='服务端压缩不可用，正在写入原文件…';if(kind==='audio')alert(`${error instanceof Error?error.message:'语音压缩失败'}；当前文件将原样放入工程包。请开启资源存储并配置 FFmpeg 以启用 128kbps Ogg Opus 压缩。`);const extension=file.name.split('.').pop()?.toLowerCase()||'bin';const digest=await crypto.subtle.digest('SHA-256',original);const hash=Array.from(new Uint8Array(digest),value=>value.toString(16).padStart(2,'0')).join('');return{bytes:original,asset:{id:`${hash}.${extension}`,mime:file.type||`${kind}/*`,name:file.name} as StoryAssetRef}}}
