async function addAudio(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const task=beginUploadTask(file,'audio');try{const prepared=await prepareUploadedMedia(file,'audio',task);update(a=>{a.assets.set(prepared.asset.id,prepared.bytes);const index=insertionIndex(a.document.messages);a.document.messages.splice(index,0,{id:createStoryId('message'),kind:'audio',characterId:selectedCharacterId.value,asset:prepared.asset,alt:'语音',caption:undefined,time:0,locallyInserted:true,sourceFingerprint:''})});finishUploadTask(task,'语音已添加');cancelInsert()}catch(error){finishUploadTask(task,error instanceof Error?error.message:'语音上传失败','error')}finally{input.value=''}}
