function validateRemoteMedia(url:string,kind:'image'|'audio'):Promise<number>{return new Promise((resolve,reject)=>{let parsed:URL;try{parsed=new URL(url)}catch{reject(new Error('链接格式无效'));return}if(parsed.protocol!=='https:'&&parsed.protocol!=='http:'){reject(new Error('只允许 HTTP 或 HTTPS 链接'));return}let done=false;const finish=(error?:Error,duration=0)=>{if(done)return;done=true;clearTimeout(timer);error?reject(error):resolve(duration)};const timer=setTimeout(()=>finish(new Error('资源验证超时或链接不可访问')),15000);if(kind==='image'){const image=new Image();image.onload=()=>finish();image.onerror=()=>finish(new Error('图片链接无效或已经失效'));image.src=parsed.toString()}else{const audio=globalThis.document.createElement('audio');audio.preload='metadata';audio.onloadedmetadata=()=>finish(undefined,Number.isFinite(audio.duration)?Math.round(audio.duration*1000):0);audio.onerror=()=>finish(new Error('语音链接无效、格式不支持或已经失效'));audio.src=parsed.toString();audio.load()}})}
